function applyLanguage(lang){
 document.documentElement.lang=lang==='pt'?'pt-PT':lang;
 document.title='AssessFirst — '+internationalText('Construisons la suite',lang);
 const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
 let node;
 while((node=walker.nextNode())){
   if(['SCRIPT','STYLE','TEXTAREA'].includes(node.parentElement?.tagName))continue;
   if(!node.nodeValue.trim())continue;
   if(!originalText.has(node))originalText.set(node,node.nodeValue);
   node.nodeValue=internationalText(originalText.get(node),lang);
 }
 document.querySelectorAll('[aria-label],[placeholder]').forEach(el=>{
   if(!originalAttributes.has(el))originalAttributes.set(el,{label:el.getAttribute('aria-label'),placeholder:el.getAttribute('placeholder')});
   const original=originalAttributes.get(el);
   if(original.label)el.setAttribute('aria-label',internationalText(original.label,lang));
   if(original.placeholder)el.setAttribute('placeholder',internationalText(original.placeholder,lang));
 });
 document.querySelectorAll('[data-language]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.language===lang)));
}

