for(const lang of Object.keys(INTERNATIONAL)){
 const dict=INTERNATIONAL[lang];
 for(const key of Object.keys(dict))dict[key.toLocaleUpperCase('en')]=dict[key].toLocaleUpperCase(lang);
}
const LANGUAGE_WORDS={it:{who:'chi fa cosa?',order:'Il tuo ordine cliente',revenue:'Il tuo ricavo',months:'mesi',commitment:'impegno di $1 mesi',annual:'prezzo annuo',tokens:'token',screen:'SCHERMATA'},es:{who:'¿quién hace qué?',order:'Tu pedido de cliente',revenue:'Tu ingreso',months:'meses',commitment:'compromiso de $1 meses',annual:'precio anual',tokens:'tokens',screen:'PANTALLA'},pt:{who:'quem faz o quê?',order:'A sua encomenda de cliente',revenue:'A sua receita',months:'meses',commitment:'compromisso de $1 meses',annual:'preço anual',tokens:'tokens',screen:'ECRÃ'}};
function internationalText(raw,lang){
 const text=String(raw);
 if(lang==='fr')return text;
 const english=translateText(text);
 if(lang==='en')return english;
 const dict=INTERNATIONAL[lang],w=LANGUAGE_WORDS[lang];
 if(!dict)return english;
 const trimmed=english.trim();
 if(dict[trimmed])return english.replace(trimmed,dict[trimmed]);
 const prefix=trimmed.match(/^(\d{2} \/ 06 · )(.+)$/);
 if(prefix)return prefix[1]+internationalText(prefix[2],lang);
 const roles=trimmed.match(/^(Referral|Advisory|Reseller|Distributor) — who does what\?$/);
 if(roles)return (dict[roles[1]]||roles[1])+' — '+w.who;
 let value=english;
 value=value.replace(/your client order/gi,m=>m===m.toUpperCase()?w.order.toLocaleUpperCase(lang):w.order).replace(/your revenue/gi,m=>m===m.toUpperCase()?w.revenue.toLocaleUpperCase(lang):w.revenue);
 // Dynamic pricing summaries contain a few fixed fragments and locale-formatted numbers.
 for(const phrase of ['Fewer than 250 employees','250–1,000 employees','More than 1,000 employees','Reseller','Distributor']){
   value=value.split(phrase).join(dict[phrase]||phrase);
   value=value.split(phrase.toUpperCase()).join((dict[phrase]||phrase).toLocaleUpperCase(lang));
 }
 value=value.replace(/(\d+)-month commitment/g,w.commitment).replace(/(\d+) months/g,'$1 '+w.months).replace(/annual price/g,w.annual).replace(/tokens/g,w.tokens);
 value=value.replace(/^ÉCRAN |^SCREEN /,w.screen+' ');
 return value;
}
